(() => {
  "use strict";
  const MASCOT = "data:image/webp;base64,";
  const BANNER = 'data:image/webp;base64,';
  const ICONS = {
    "Alface":"🥬","Tomate":"🍅","Cebola":"🧅","Cebolinha":"🌿","Coentro":"🌿",
    "Cenoura":"🥕","Batata":"🥔","Batata-doce":"🍠","Pimentão":"🫑","Pimenta":"🌶️",
    "Abóbora":"🎃","Abobrinha":"🥒","Couve":"🥬","Beterraba":"🫜","Alho":"🧄",
    "Feijão":"🫘","Milho":"🌽","Trigo":"🌾","Mandioca":"🌱","Arroz":"🌾","Soja":"🌱",
    "Outra / Personalizada":"🌱"
  };
  const iconFor = n => ICONS[String(n || "").trim()] || "🌱";

  function styles() {
    if (document.getElementById("irrigasenseVisualV7")) return;
    const s = document.createElement("style");
    s.id = "irrigasenseVisualV7";
    s.textContent = `
      /* ===== V7: FUNDO + RESPONSIVIDADE + MENU LIMPO ===== */
      .nav{
        scrollbar-width:none!important;
        -ms-overflow-style:none!important;
      }
      .nav::-webkit-scrollbar{
        width:0!important;
        height:0!important;
        display:none!important;
      }

      .hero{
        position:relative!important;
        overflow:hidden!important;
        color:#fff!important;
        background:
          linear-gradient(105deg,rgba(3,31,22,.92) 0%,rgba(4,58,38,.84) 47%,rgba(6,80,48,.62) 72%,rgba(6,55,39,.72) 100%),
          url("${BANNER}") center/cover no-repeat!important;
        box-shadow:0 24px 60px rgba(0,0,0,.18)!important;
      }
      .hero::after{
        content:"";
        position:absolute;
        inset:0;
        pointer-events:none;
        background:radial-gradient(circle at 77% 48%,rgba(70,207,111,.15),transparent 31%);
        z-index:1;
      }
      .hero-copy{position:relative!important;z-index:3!important}
      .hero-copy p{color:rgba(255,255,255,.88)!important}
      .hero-stats span{color:rgba(255,255,255,.82)!important}
      .hero-stats strong{color:#fff!important}
      .hero-visual{position:relative!important;z-index:2!important;background:transparent!important}
      .hero-plant{display:none!important}

      #irrigasenseMascotHero{
        display:block!important;
        background:transparent!important;
        border:0!important;
        box-shadow:none!important;
        object-fit:contain!important;
        filter:drop-shadow(0 24px 24px rgba(0,0,0,.32));
        z-index:2!important;
      }

      .hero .floating-card{
        background:rgba(4,42,29,.94)!important;
        color:#fff!important;
        border:1px solid rgba(255,255,255,.28)!important;
        box-shadow:0 14px 34px rgba(0,0,0,.28)!important;
        backdrop-filter:blur(12px);
        -webkit-backdrop-filter:blur(12px);
        z-index:5!important;
      }
      .hero .floating-card small{color:#bfdbcc!important;opacity:1!important}
      .hero .floating-card strong{color:#fff!important;opacity:1!important}
      .hero .floating-card span{color:#e0eee7!important;opacity:1!important}

      /* Contraste das seções abaixo da Home no tema escuro. */
      body.dark .section-heading .kicker,
      body.dark .section .kicker,
      body.dark .page-intro .kicker{color:#70e5a6!important}
      body.dark .section-heading h2,
      body.dark .section h2,
      body.dark .page-intro h2{color:#f4fbf7!important}
      body.dark .section-heading p,
      body.dark .section p{color:#afc7bb!important}

      .crop-icon-inline{
        width:36px;height:36px;flex:0 0 36px;border-radius:50%;display:inline-grid;place-items:center;font-size:1.2rem;
        background:var(--green-soft);border:1px solid var(--line)
      }
      .crop-heading-row{display:flex!important;align-items:center!important;gap:9px!important;min-width:0!important}
      .culture-symbol-chip{
        display:inline-flex;align-items:center;gap:8px;width:max-content;max-width:100%;margin:8px 0 2px;padding:7px 11px;
        border-radius:999px;background:var(--surface2);border:1px solid var(--line);color:var(--text);font-size:.86rem;font-weight:800
      }
      .culture-symbol-chip span{font-size:1.2rem}

      /* Desktop grande */
      @media (min-width:1251px){
        .hero{
          display:grid!important;
          grid-template-columns:minmax(0,1.10fr) minmax(390px,.90fr)!important;
          min-height:570px!important;
        }
        .hero-copy{padding:clamp(44px,4.2vw,66px)!important;min-width:0!important}
        .hero-copy h2{font-size:clamp(42px,4.7vw,68px)!important;line-height:1.01!important;max-width:690px!important}
        .hero-visual{min-height:570px!important;display:block!important;overflow:hidden!important}
        #irrigasenseMascotHero{
          position:absolute!important;
          width:315px!important;
          max-height:420px!important;
          right:4%!important;
          left:auto!important;
          bottom:5px!important;
          transform:none!important;
        }
        .hero .floating-card{position:absolute!important;min-width:148px!important;max-width:180px!important}
        .hero .floating-card.f1{left:3%!important;top:17%!important;right:auto!important;bottom:auto!important}
        .hero .floating-card.f2{right:3%!important;top:17%!important;left:auto!important;bottom:auto!important}
        .hero .floating-card.f3{left:3%!important;bottom:8%!important;right:auto!important;top:auto!important}
      }

      /* Notebook: mascot à direita, card Modo à esquerda, sem sobreposição. */
      @media (min-width:1001px) and (max-width:1250px){
        :root{--sidebar:248px!important}
        .content{padding:20px!important}
        .hero{
          display:grid!important;
          grid-template-columns:minmax(0,1.12fr) minmax(330px,.88fr)!important;
          min-height:540px!important;
        }
        .hero-copy{padding:38px!important;min-width:0!important}
        .hero-copy h2{font-size:clamp(38px,4.25vw,56px)!important;line-height:1.01!important}
        .hero-stats{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:14px!important}
        .hero-visual{min-height:540px!important;display:block!important;overflow:hidden!important}
        #irrigasenseMascotHero{
          position:absolute!important;
          width:245px!important;
          max-height:350px!important;
          right:0!important;
          left:auto!important;
          bottom:4px!important;
          transform:none!important;
        }
        .hero .floating-card{
          position:absolute!important;
          min-width:132px!important;
          max-width:150px!important;
          padding:11px 12px!important;
        }
        .hero .floating-card.f1{left:2%!important;top:15%!important;right:auto!important;bottom:auto!important}
        .hero .floating-card.f2{right:2%!important;top:17%!important;left:auto!important;bottom:auto!important}
        .hero .floating-card.f3{left:2%!important;bottom:7%!important;right:auto!important;top:auto!important}
      }

      /* Tablet */
      @media (min-width:761px) and (max-width:1000px){
        .content{padding:22px!important}
        .hero{display:grid!important;grid-template-columns:1fr!important;min-height:auto!important}
        .hero-copy{padding:42px!important}
        .hero-visual{
          min-height:430px!important;
          display:grid!important;
          grid-template-columns:repeat(2,minmax(0,1fr))!important;
          gap:10px!important;
          padding:0 36px 32px!important;
          overflow:hidden!important;
        }
        #irrigasenseMascotHero{grid-column:1/-1;width:min(340px,68%)!important;height:285px!important;margin:0 auto!important}
        .hero .floating-card{position:relative!important;inset:auto!important;min-width:0!important;width:auto!important;transform:none!important}
        .hero .floating-card.f3{grid-column:1/-1!important}
      }

      /* Celular */
      @media (max-width:760px){
        html,body{max-width:100%;overflow-x:hidden}
        .content{padding:20px 12px!important}
        .topbar{padding:10px 12px!important;gap:8px!important}
        .topbar-title{min-width:0!important}
        .topbar-title h1{font-size:1.05rem!important}
        #topSystemPill{max-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

        .hero{
          display:block!important;
          min-height:auto!important;
          border-radius:24px!important;
          background:
            linear-gradient(180deg,rgba(2,32,22,.86) 0%,rgba(4,66,42,.76) 52%,rgba(4,79,47,.72) 100%),
            url("${BANNER}") center/cover no-repeat!important;
        }
        .hero-copy{padding:34px 28px 20px!important}
        .hero-copy h2{font-size:clamp(2.35rem,10.2vw,3.25rem)!important;line-height:1.02!important;letter-spacing:-.045em!important}
        .hero-copy p{font-size:1rem!important;line-height:1.58!important}
        .hero-actions{display:grid!important;grid-template-columns:1fr!important}
        .hero-actions .btn{width:100%!important}
        .hero-stats{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:16px!important}
        .hero-stats div:last-child{grid-column:1/-1}
        .hero-visual{
          display:grid!important;
          grid-template-columns:repeat(2,minmax(0,1fr))!important;
          gap:10px!important;
          min-height:auto!important;
          padding:8px 20px 26px!important;
          align-items:stretch!important;
          overflow:hidden!important;
        }
        #irrigasenseMascotHero{
          grid-column:1/-1!important;
          width:min(255px,76%)!important;
          height:235px!important;
          margin:4px auto 4px!important;
        }
        .hero .floating-card{
          position:relative!important;
          inset:auto!important;
          transform:none!important;
          min-width:0!important;
          width:auto!important;
          padding:12px!important;
          border-radius:15px!important;
        }
        .hero .floating-card.f3{grid-column:1/-1!important;justify-self:center!important;width:min(260px,100%)!important}
        .hero .floating-card small{font-size:.66rem!important}
        .hero .floating-card strong{font-size:.92rem!important}
        .hero .floating-card span{font-size:.70rem!important}
        .cards.four,.cards.three,.dashboard-grid,.summary-grid,.system-grid,.config-grid,.manual-grid,.profiles-grid,.connect-grid,.team-grid,.schedule-grid{grid-template-columns:1fr!important}
        canvas{min-width:0!important;max-width:100%!important;width:100%!important}
      }

      @media(max-width:390px){
        #topSystemPill{display:none!important}
        .hero-copy{padding-left:20px!important;padding-right:20px!important}
        .hero-stats{grid-template-columns:1fr!important}
        .hero-stats div:last-child{grid-column:auto}
        .hero-visual{grid-template-columns:1fr!important;padding-left:16px!important;padding-right:16px!important}
        .hero .floating-card.f3{grid-column:auto!important;width:100%!important}
      }
    `;
    document.head.appendChild(s);
  }

  function culture(zone) {
    const sel = document.getElementById(`culture${zone}`);
    if (sel?.value) return sel.value;
    const dash = document.getElementById(`dashCrop${zone}`);
    return dash?.textContent?.trim() || (zone === 1 ? "Tomate" : "Feijão");
  }

  function mascot() {
    const v = document.querySelector(".hero-visual");
    if (!v) return;
    let img = document.getElementById("irrigasenseMascotHero");
    if (!img) {
      img = document.createElement("img"); img.id = "irrigasenseMascotHero"; img.alt = "Mascote IrrigaSense"; v.prepend(img);
    }
    img.src = MASCOT;
  }

  function heading(el, zone) {
    if (!el?.parentElement) return;
    const p = el.parentElement, c = culture(zone);
    p.classList.add("crop-heading-row");
    let i = p.querySelector(":scope > .crop-icon-inline");
    if (!i) { i = document.createElement("span"); i.className = "crop-icon-inline"; p.insertBefore(i, el); }
    i.textContent = iconFor(c); i.title = c;
  }

  function selectIcon(zone) {
    const sel = document.getElementById(`culture${zone}`);
    if (!sel) return;
    [...sel.options].forEach(o => {
      if (!o.dataset.plainLabel) o.dataset.plainLabel = o.textContent.trim();
      const plain = o.dataset.plainLabel;
      o.textContent = `${iconFor(o.value || plain)} ${plain}`;
    });
    const label = sel.closest("label");
    if (label) {
      let chip = document.getElementById(`cultureSymbolChip${zone}`);
      if (!chip) { chip = document.createElement("div"); chip.id = `cultureSymbolChip${zone}`; chip.className = "culture-symbol-chip"; label.insertAdjacentElement("afterend", chip); }
      const c = culture(zone); chip.innerHTML = `<span>${iconFor(c)}</span><b>${c}</b>`;
    }
    if (!sel.dataset.visualBound) {
      sel.dataset.visualBound = "1"; sel.addEventListener("change", () => setTimeout(all, 0));
    }
  }

  function schedules() {
    document.querySelectorAll(".schedule-card").forEach((card, i) => {
      const z = Number(card.dataset.scheduleZone || i + 1);
      const h = card.querySelector(".config-title h3"); if (h) heading(h, z);
    });
  }

  function all() {
    selectIcon(1); selectIcon(2);
    heading(document.getElementById("manualName1"), 1); heading(document.getElementById("manualName2"), 2);
    heading(document.getElementById("chartTitle1"), 1); heading(document.getElementById("chartTitle2"), 2);
    schedules();
  }

  function bind() {
    [1,2].forEach(z => {
      const d = document.getElementById(`dashCrop${z}`);
      if (d && !d.dataset.visualObserved) {
        d.dataset.visualObserved = "1";
        new MutationObserver(all).observe(d, {childList:true,subtree:true,characterData:true});
      }
    });
    document.addEventListener("click", e => {
      if (e.target.closest(".nav-item,[data-jump]")) setTimeout(all, 80);
    }, {passive:true});
  }

  function init() {
    styles(); mascot(); all(); bind();
    setTimeout(() => { mascot(); all(); }, 500);
    setTimeout(() => { mascot(); all(); }, 1200);
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init, {once:true});
  else init();
})();
